static int
expand_number(const char *buf, du_off_t *num)
{
    char *endptr;
    errno = 0;
    long long value = strtoll(buf, &endptr, 10);
    if (errno == ERANGE)
        return -1;
    if (endptr == buf)
        return -1;
    if (*endptr != '\0') {
        long long factor = 0;
        switch (tolower((unsigned char)*endptr)) {
        case 'b': factor = 512; break;
        case 'k': factor = 1024; break;
        case 'm': factor = 1024LL * 1024; break;
        case 'g': factor = 1024LL * 1024 * 1024; break;
        case 't': factor = 1024LL * 1024 * 1024 * 1024; break;
        case 'p': factor = 1024LL * 1024 * 1024 * 1024 * 1024; break;
        case 'e': factor = 1024LL * 1024 * 1024 * 1024 * 1024 * 1024; break;
        default: return -1;
        }
        if (value > LLONG_MAX / factor || value < LLONG_MIN / factor)
            return -1;
        value *= factor;
        endptr++;
        if (*endptr != '\0')
            return -1;
    }
    *num = value;
    return 0;
}
```
